import{_ as e,o as r,c as i,a2 as n}from"./chunks/framework.CDpkVv68.js";const h=JSON.parse('{"title":"Carpintería","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/professions/carpentry.md","filePath":"es/guide/professions/carpentry.md"}'),t={name:"es/guide/professions/carpentry.md"};function o(s,a,c,d,l,p){return r(),i("div",null,[...a[0]||(a[0]=[n('<h1 id="carpentry" tabindex="-1">Carpintería <a class="header-anchor" href="#carpentry" aria-label="Enlace permanente a &quot;Carpintería&quot;">​</a></h1><p><strong>Estado:</strong> Propuesto · No establecido como jugable.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Enlace permanente a &quot;TL;DR&quot;">​</a></h2><ul><li>Convierte el conocimiento de la madera en equipo, construcción y estructuras de campo.</li><li>La preparación, la veta y las uniones deben importar sin simular cada corte.</li><li>Fabricar arcos es un camino de técnicas aprendidas, no una recompensa automática de Carpintería.</li></ul><p><span id="what-it-does"></span><span id="why-take-it-into-the-field"></span><span id="learning-and-specialization"></span></p><h2 id="how-it-works" tabindex="-1">Cómo funciona <a class="header-anchor" href="#how-it-works" aria-label="Enlace permanente a &quot;Cómo funciona&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Actividad</th><th>Qué haces</th></tr></thead><tbody><tr><td>Trabajar la madera</td><td>Seca, selecciona, corta, da forma, une, monta y acaba.</td></tr><tr><td>Crear estructuras útiles</td><td>Muebles, contenedores, mangos, escudos, estructuras de campamento y soportes de mina son productos posibles.</td></tr><tr><td>Aprender</td><td>Amplía un diario de carpintería mediante maestros, manuscritos, desafíos y exploración.</td></tr></tbody></table><h2 id="compared-with-classic-uo" tabindex="-1">Comparado con UO clásico <a class="header-anchor" href="#compared-with-classic-uo" aria-label="Enlace permanente a &quot;Comparado con UO clásico&quot;">​</a></h2><table tabindex="0"><thead><tr><th>UO clásico</th><th>Dirección de Syrolands</th></tr></thead><tbody><tr><td>Carpintería ya crea muebles y estructuras de taller, a veces con otras habilidades.</td><td>La preparación de materiales y las decisiones de construcción amplían esa función en expediciones.</td></tr><tr><td>Bowcraft and Fletching es una habilidad separada en UO.</td><td>La fabricación de arcos se plantea como un camino aprendido de Carpintería/Archery.</td></tr></tbody></table><p>La comparación usa los ciclos conocidos de los oficios de UO; las referencias oficiales también cubren expansiones posteriores. <a href="https://uo.com/wiki/ultima-online-wiki/skills/carpentry/" target="_blank" rel="noreferrer">Carpentry</a> · <a href="https://uo.com/wiki/ultima-online-wiki/skills/bowcraft-and-fletching/" target="_blank" rel="noreferrer">Bowcraft And Fletching</a>.</p><h2 id="bowmaking-and-fletching" tabindex="-1">Fabricación de arcos y flechas <a class="header-anchor" href="#bowmaking-and-fletching" aria-label="Enlace permanente a &quot;Fabricación de arcos y flechas&quot;">​</a></h2><p>Aprende este camino mediante Carpintería y Archery, con apoyo opcional de Sastrería y Herrería. Seca y da forma a la vara, equilibra las palas, encuerda, ajusta y prueba el arco. Las flechas combinan astiles, puntas, emplumado y montaje; sus funciones exactas siguen abiertas. La identidad de maestro fabricante de arcos debe requerir conocimiento y práctica sostenidos.</p><h2 id="example" tabindex="-1">Ejemplo <a class="header-anchor" href="#example" aria-label="Enlace permanente a &quot;Ejemplo&quot;">​</a></h2><p>Un arquero aprende a fabricar arcos con un maestro y practica la selección de una vara, el equilibrado de las palas y el ajuste. Carpintería por sí sola no le daría ese conocimiento.</p><h2 id="progression-and-trade-offs" tabindex="-1">Progresión y compromisos <a class="header-anchor" href="#progression-and-trade-offs" aria-label="Enlace permanente a &quot;Progresión y compromisos&quot;">​</a></h2><ul><li>Camping, Minería, Mecánica y Herrería pueden contribuir a estructuras y objetos compuestos. Las reglas de colocación y protección siguen abiertas.</li><li>La lutería y los componentes navales siguen siendo posibles caminos futuros. Los personajes existentes con Bowcraft aún necesitan una política de transición explícita.</li></ul><h2 id="related" tabindex="-1">Relacionado <a class="header-anchor" href="#related" aria-label="Enlace permanente a &quot;Relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/guide/professions/lumberjacking.html">Tala</a> · <a href="/Syrolands-Public/es/guide/professions/mining.html">Minería</a> · <a href="/Syrolands-Public/es/guide/professions/tinkering.html">Mecánica</a> · <a href="/Syrolands-Public/es/guide/items/item-quality.html">Calidad de objetos</a> · <a href="/Syrolands-Public/es/guide/professions/overview.html">Sistema de profesiones</a></p><h2 id="full-design-specification" tabindex="-1">Especificación de diseño completa <a class="header-anchor" href="#full-design-specification" aria-label="Enlace permanente a &quot;Especificación de diseño completa&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Carpintería</a></p>',20)])])}const m=e(t,[["render",o]]);export{h as __pageData,m as default};
